import{_ as n,B as s,o as r,c as o,a8 as t,a as l,f as a,E as d}from"./chunks/framework.CNIpabDg.js";const x=JSON.parse('{"title":"Integrate Xila into a host application","description":"Assemble a host Xila runtime with explicit managers, drivers, and executable capabilities.","frontmatter":{"layout":"doc","docType":"how-to","description":"Assemble a host Xila runtime with explicit managers, drivers, and executable capabilities."},"headers":[],"relativePath":"how-to/integrate-host.md","filePath":"how-to/integrate-host.md","lastUpdated":1793145952000}'),h={name:"how-to/integrate-host.md"};function c(p,e,u,m,g,b){const i=s("CodeReference");return r(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[2]||(e[2]=t('<h1 id="integrate-xila-into-a-host-application" tabindex="-1">Integrate Xila into a host application <a class="header-anchor" href="#integrate-xila-into-a-host-application" aria-label="Permalink to &quot;Integrate Xila into a host application&quot;">​</a></h1><p>Use the native example&#39;s assembly to connect Xila services and executables to your host application.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>Complete the <a href="/tutorials/native.html">native tutorial</a> or establish a working <a href="./setup-development.html">development environment</a>. Read the <a href="/explanation/architecture/#runtime-assembly">runtime assembly overview</a> and identify your display, time, storage, and executor drivers.</p>',4)),l("p",null,[e[0]||(e[0]=a("The procedure is an integration outline; ",-1)),d(i,{repo:"platforms",path:"examples/native/src/main.rs"}),e[1]||(e[1]=a(" provides the complete executable example.",-1))]),e[3]||(e[3]=t(`<h2 id="add-the-dependencies" tabindex="-1">Add the dependencies <a class="header-anchor" href="#add-the-dependencies" aria-label="Permalink to &quot;Add the dependencies&quot;">​</a></h2><p>In your application&#39;s Cargo manifest:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">xila = { git = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/Xila-Project/Core.git&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, features = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;graphics_rendering_xrgb8888&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>This enables Core&#39;s default services and the optional XRGB8888 graphics rendering path. Select features appropriate to your actual display. The package has no <code>host</code> feature.</p><p>Add platform drivers separately, such as <code>drivers_std</code> and <code>drivers_native</code>; they are not re-exported through <code>xila::drivers</code>.</p><h2 id="assemble-the-runtime" tabindex="-1">Assemble the runtime <a class="header-anchor" href="#assemble-the-runtime" aria-label="Permalink to &quot;Assemble the runtime&quot;">​</a></h2><ol><li>Construct a task manager and connect it to your executor bootstrap, following the example&#39;s <code>#[task::run(...)]</code> manager argument.</li><li>Register the allocator/logger and construct users/time managers with their platform drivers.</li><li>Initialize graphics with the time manager and screen/input devices. Register the FFI manager for callbacks that cannot carry Rust references.</li><li>Construct VFS from task/users/time managers and a root filesystem; create the default hierarchy and mount devices. Register the separate C ABI runtime context if your runtime uses it.</li><li>Initialize optional networking with its task/VFS/time/random dependencies.</li><li>Build an <code>ExecutableContext</code>, mount executables with it, and open <code>Standard</code> streams carrying the same context.</li><li>Launch with <code>executable::execute(context, path, args, standard, spawner)</code> and join the returned task when needed.</li></ol><p>Keep manager storage alive for its consumers. The examples use static storage and leaked boxes for required <code>&#39;static</code> references; plan ownership and RAM costs for your target.</p><h2 id="verify-completion" tabindex="-1">Verify completion <a class="header-anchor" href="#verify-completion" aria-label="Permalink to &quot;Verify completion&quot;">​</a></h2><p>Build for your actual host target, start the runtime, and launch a mounted executable. Check that it uses the same context/VFS that created its streams. For graphical integration, exercise input and window closing in the supported native session.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><a href="/explanation/architecture/libraries/executable.html">Executable context</a>.</li><li><a href="/explanation/architecture/subsystems/virtual_file_system.html">VFS</a>.</li><li><a href="/explanation/architecture/libraries/abi.html">C ABI context</a>.</li><li><a href="/explanation/development-environments.html">Development environments and targets</a>.</li></ul>`,12))])}const k=n(h,[["render",c]]);export{x as __pageData,k as default};
